package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class AccountManager {
    public record Account(String tier, String currency, BigDecimal balance) {}

    private final Map<String, Account> accounts = new HashMap<>();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        accounts.put(id, new Account(tier, currency, new BigDecimal(openingBalance).setScale(2)));
    }

    public Account getAccount(String id) {
        return accounts.get(id);
    }

    public void updateBalance(String id, BigDecimal delta) {
        Account a = accounts.get(id);
        accounts.put(id, new Account(a.tier(), a.currency(), a.balance().add(delta)));
    }

    public boolean exists(String id) {
        return accounts.containsKey(id);
    }
}

package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

public class TransactionStore {
    public record Transaction(String verb, String date, String fromId, String toId, 
                             BigDecimal amount, String currency, BigDecimal fee, 
                             BigDecimal credited, boolean reversed) {}

    private final Map<String, Transaction> txs = new LinkedHashMap<>();
    private int txSeq = 0;

    public String save(Transaction tx) {
        txSeq++;
        String id = String.format("TX-%06d", txSeq);
        txs.put(id, tx);
        return id;
    }

    public Transaction get(String id) {
        return txs.get(id);
    }

    public void updateReversed(String id, boolean reversed) {
        Transaction tx = txs.get(id);
        txs.put(id, new Transaction(tx.verb(), tx.date(), tx.fromId(), tx.toId(), 
                                   tx.amount(), tx.currency(), tx.fee(), tx.credited(), reversed));
    }
}

package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return new BigDecimal("0.00");
    }

    public BigDecimal calculateWithdrawFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : new BigDecimal("0.00");
    }
}

package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    private BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) return new BigDecimal("4.30");
        if ("USD".equals(currency)) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class LimitChecker {
    private final Map<String, BigDecimal> used = new HashMap<>();

    public String checkLimitAndFunds(String date, String id, AccountManager.Account a, 
                                   BigDecimal amount, BigDecimal fee) {
        BigDecimal limit, overdraft = BigDecimal.ZERO;
        if ("STANDARD".equals(a.tier())) limit = new BigDecimal("5000.00");
        else if ("PREMIUM".equals(a.tier())) {
            limit = new BigDecimal("20000.00");
            overdraft = new BigDecimal("500.00");
        } else limit = new BigDecimal("50000.00");

        if (usedToday(id, date).add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.tier();
        }
        BigDecimal needed = amount.add(fee);
        if (a.balance().subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance() + " " + a.currency() + 
                   ", needed " + needed + " " + a.currency();
        }
        return null;
    }

    public void addUsed(String id, String date, BigDecimal amount) {
        used.put(id + "|" + date, usedToday(id, date).add(amount));
    }

    private BigDecimal usedToday(String id, String date) {
        return used.getOrDefault(id + "|" + date, new BigDecimal("0.00"));
    }
}

