package com.rustyledger.legacy;

import java.math.BigDecimal;
import java.util.*;

public class ReportGenerator {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[slot]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    public String generateReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }
}

package com.rustyledger.legacy;

public class InstructionParser {
    public record ParseResult(String verb, String date, String[] fields, String errorCode, String errorMessage) {}

    public ParseResult parse(String line) {
        if (line == null || line.trim().isEmpty()) {
            return new ParseResult("???", null, null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> -1;
        };
        if (want == -1) return new ParseResult("???", null, null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) return new ParseResult(verb, null, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return new ParseResult(verb, null, null, "BAD_DATE", date);
        return new ParseResult(verb, date, f, null, null);
    }
}

