package com.rustyledger.legacy;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.util.List;

public class TransactionManager implements Ledger {
    private final AccountManager accounts = new AccountManager();
    private final TransactionStore txStore = new TransactionStore();
    private final FeeCalculator feesCalc = new FeeCalculator();
    private final CurrencyConverter converter = new CurrencyConverter();
    private final LimitChecker limitChecker = new LimitChecker();
    private final AuditLogger logger = new AuditLogger();
    private final ReportGenerator reportGen = new ReportGenerator();
    private final InstructionParser parser = new InstructionParser();

    public void openAccount(String id, String tier, String currency, String balance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!List.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!List.of("PLN", "EUR", "USD").contains(currency)) throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (balance == null || !balance.matches("\\d+(\\.\\d{1,2})?")) throw new IllegalArgumentException("INVALID AMOUNT: " + balance);
        if (accounts.exists(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        accounts.openAccount(id, tier, currency, balance);
    }

    public String balance(String id) {
        AccountManager.Account a = accounts.getAccount(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance() + " " + a.currency();
    }

    public List<String> auditLog() { return logger.getLog(); }
    public String dailyReport(String date) { return reportGen.generateReport(date); }

    public String submit(String line) {
        InstructionParser.ParseResult res = parser.parse(line);
        if (res.errorCode() != null) return reject(res.verb(), res.date(), res.errorCode(), res.errorMessage());

        String verb = res.verb();
        String date = res.date();
        String[] f = res.fields();
        if ("REVERSE".equals(verb)) return doReverse(date, f[2]);

        String amtTxt = "TRANSFER".equals(verb) ? f[4] : f[3];
        if (!amtTxt.matches("\\d+(\\.\\d{1,2})?") || new BigDecimal(amtTxt).signum() <= 0) {
            return reject(verb, date, "BAD_AMOUNT", amtTxt);
        }
        BigDecimal amt = new BigDecimal(amtTxt).setScale(2);
        return switch (verb) {
            case "TRANSFER" -> doTransfer(date, f[2], f[3], amt, f[5]);
            case "WITHDRAW" -> doWithdraw(date, f[2], amt);
            case "DEPOSIT" -> doDeposit(date, f[2], amt);
            default -> reject("???", date, "BAD_INSTRUCTION", "unknown verb");
        };
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amount, String currency) {
        AccountManager.Account from = accounts.getAccount(fromId);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        AccountManager.Account to = accounts.getAccount(toId);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency().equals(currency)) return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.currency());

        BigDecimal fee = feesCalc.calculateTransferFee(from.tier(), amount);
        String rej = limitChecker.checkLimitAndFunds(date, fromId, from, amount, fee);
        if (rej != null) return reject("TRANSFER", date, rej.split(":")[0], rej.substring(rej.indexOf(':') + 2));

        BigDecimal credited = from.currency().equals(to.currency()) ? amount : converter.convert(amount, from.currency(), to.currency(), from.tier());
        accounts.updateBalance(fromId, amount.add(fee).negate());
        accounts.updateBalance(toId, credited);
        limitChecker.addUsed(fromId, date, amount);

        String txId = txStore.save(new TransactionStore.Transaction("TRANSFER", date, fromId, toId, amount, from.currency(), fee, credited, false));
        reportGen.addFee(date, from.currency(), fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.currency());
    }

    private String doWithdraw(String date, String id, BigDecimal amount) {
        AccountManager.Account a = accounts.getAccount(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = feesCalc.calculateWithdrawFee(a.tier());
        String rej = limitChecker.checkLimitAndFunds(date, id, a, amount, fee);
        if (rej != null) return reject("WITHDRAW", date, rej.split(":")[0], rej.substring(rej.indexOf(':') + 2));

        accounts.updateBalance(id, amount.add(fee).negate());
        limitChecker.addUsed(id, date, amount);
        String txId = txStore.save(new TransactionStore.Transaction("WITHDRAW", date, id, "", amount, a.currency(), fee, amount, false));
        reportGen.addFee(date, a.currency(), fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.currency());
    }

    private String doDeposit(String date, String id, BigDecimal amount) {
        AccountManager.Account a = accounts.getAccount(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        accounts.updateBalance(id, amount);
        String txId = txStore.save(new TransactionStore.Transaction("DEPOSIT", date, id, "", amount, a.currency(), BigDecimal.ZERO, amount, false));
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.currency());
    }

    private String doReverse(String date, String txId) {
        TransactionStore.Transaction tx = txStore.get(txId);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", txId);
        if (!"TRANSFER".equals(tx.verb())) return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.verb());
        if (tx.reversed()) return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        if (!tx.date().equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.date());

        AccountManager.Account from = accounts.getAccount(tx.fromId());
        AccountManager.Account to = accounts.getAccount(tx.toId());
        accounts.updateBalance(tx.toId(), tx.credited().negate());
        BigDecimal back = tx.amount();
        if ("PREMIUM".equals(from.tier())) {
            back = back.add(tx.fee());
            reportGen.addFee(date, from.currency(), tx.fee().negate());
        }
        accounts.updateBalance(tx.fromId(), back);
        txStore.updateReversed(txId, true);
        String newId = txStore.save(new TransactionStore.Transaction("REVERSE", date, tx.fromId(), tx.toId(), tx.amount(), tx.currency(), BigDecimal.ZERO, tx.credited(), true));
        return accept("REVERSE", date, newId, "reversed " + txId);
    }

    private String accept(String verb, String date, String txId, String extra) {
        reportGen.count(date, 0);
        logger.log(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String msg) {
        if (date != null) reportGen.count(date, 1);
        logger.log(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + msg;
    }
